import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const rambaAxesScenarios=['axe-strike-ordinary','axe-strike-dedicated','axe-mighty-ordinary','axe-mighty-dedicated','axe-death-ordinary','axe-death-dedicated'] as const;
export type RambaAxesScenario=typeof rambaAxesScenarios[number];
export function isRambaAxesScenario(name:string):name is RambaAxesScenario{return (rambaAxesScenarios as readonly string[]).includes(name);}
export function rambaAxeMode(name:RambaAxesScenario){const death=name.startsWith('axe-death'),mighty=name.startsWith('axe-mighty');return {card:death?'a2-p11-r3c2':mighty?'a2-p11-r3c1':'a2-p11-r2c3',dedicated:name.endsWith('dedicated'),use:death?6:mighty?5:4,damage:death?10:mighty?8:6,limit:death?7:mighty?6:5,far:death};}
export function makeRambaAxesScenario(name:RambaAxesScenario,players:{id:string;name:string}[],options:{level?:number;owner?:string;prepared?:boolean;guard?:'none'|'limit'|'above'}={}){
 const m=rambaAxeMode(name),guardMode=options.guard??'limit',blessed=m.far&&guardMode==='above';let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];assignCharacter(s,a,options.owner??'小人のランバ');assignCharacter(s,b,'黒騎士ガーウィン');assignCharacter(s,c,'大神官ジル');assignCharacter(s,d,'魔導王ガイナス');for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};const stats=gameStats(s,a);s.players[a]!.permanent!.warrior_level=20+(options.level??m.use)-stats.warrior_level;s.players[a]!.permanent!.spirit=20+6-stats.spirit;
 const card=takeCard(s,a,m.card),advance=takeCard(s,a,'a2-p24-r1c2'),prayer=takeCard(s,a,'必勝の祈り'),first=takeCard(s,b,'a2-p07-r1c1'),second=takeCard(s,b,'a2-p07-r1c2'),fate=takeCard(s,c,'命運凶変'),guard=guardMode==='none'?null:takeCard(s,b,m.limit===5?(guardMode==='above'?'メタルゴーレム':'王立騎士団'):m.limit===6?(guardMode==='above'?'水竜':'メタルゴーレム'):'水竜');let blessing:string|null=null;if(blessed){blessing=takeCard(s,b,'祝福');s.players[b]!.hand=s.players[b]!.hand.filter(id=>id!==blessing);s.deck.unshift(blessing);}for(const id of [a,b,c,d])trimHand(s,id,card,advance,prayer,first,second,fate,...(guard?[guard]:[]));s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];if(blessing)s.deck=[blessing,...s.deck.filter(id=>id!==blessing)];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`RAMBA_AXES_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('RAMBA_AXES_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('RAMBA_AXES_IDS');}
 for(const id of [a,b,c,d]){if(guard&&id===b)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:guard});act(id,{type:'PASS_SETUP'});}act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});if(blessing){act(a,{type:'PASS_ACTION'});for(let n=0;n<100;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===a)break;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>x!==card).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});else throw Error('RAMBA_AXES_TURN');}if(!s.players[b]!.open.includes(blessing))throw Error('RAMBA_BLESSING_DRAW');}
 if(!m.far&&options.prepared!==false){act(a,{type:'APPROACH',targetId:b,cardInstanceId:advance});for(let n=0;n<100&&s.windows?.length;n++){const w=s.windows.at(-1)!;act(w.participants[w.cursor]!,{type:'PASS'});}}return s;
}
